package com.game_manager.gm.document;
import com.game_manager.gm.common.config.GManagerProperties; import com.game_manager.gm.document.storage.DocumentStorage; import java.time.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component @ConditionalOnProperty(prefix="app.jobs",name="enabled",havingValue="true") public class DocumentCleanupWorker {private final DocumentRepository repo;private final DocumentStorage storage;private final GManagerProperties config;private final Clock clock;public DocumentCleanupWorker(DocumentRepository r,DocumentStorage s,GManagerProperties c,Clock k){repo=r;storage=s;config=c;clock=k;}@Scheduled(fixedDelayString="${app.documents.cleanup-interval-millis:3600000}")@Transactional public void cleanup(){for(Document d:repo.findByDeletedAtBefore(clock.instant().minus(Duration.ofDays(config.documents().deleteRetentionDays())))){d.getVersions().forEach(v->storage.delete(v.getObjectKey()));repo.delete(d);}}}
